package com.pousada;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class ApplicationIT {

    @Test
    void testCompleteReservationFlow() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        HttpClient client = HttpClient.newHttpClient();

        Map<String, Object> createRequest = Map.of(
            "roomNumber", "101",
            "guestName", "João Silva",
            "guestEmail", "joao@example.com",
            "guestCpf", "123.456.789-00",
            "checkIn", "2027-07-10",
            "checkOut", "2027-07-12",
            "guests", 2,
            "ratePlan", "STANDARD"
        );

        String requestBody = mapper.writeValueAsString(createRequest);
        HttpRequest createReq = HttpRequest.newBuilder()
            .uri(URI.create("http://localhost:7070/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = client.send(createReq, HttpResponse.BodyHandlers.ofString());
        assertEquals(201, response.statusCode());

        Map<String, Object> reservation = mapper.readValue(response.body(), Map.class);
        assertTrue(reservation.containsKey("id"));
        assertEquals("PENDING", reservation.get("status"));
        assertEquals(599.76, ((Number) reservation.get("subtotal")).doubleValue());
    }
}

